// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set up the contract (set MinSum to 5, Log to address(1), then Initialize)
        c.SetMinSum(5);
        c.SetLogFile(address(1));
        c.Initialized();

        // Step 2: Now attempt to call SetMinSum(10) – in reference it should revert, in second version it will succeed
        // We will catch the revert, then proceed with a deposit and Collect to expose the observable difference
        // But as per instructions, we need one assertion that diverges.
        // The difference is: in reference, after initialization, SetMinSum reverts, so MinSum stays 5.
        // In second version, SetMinSum succeeds, setting MinSum to 10.
        // Then we deposit 100 from some user, then try Collect(50).
        // In reference: MinSum=5, balance=100, so Collect(50) succeeds => transfer happens.
        // In second version: MinSum=10, balance=100, Collect(50) also succeeds? Actually 50>=10 and 50<=100, so both succeed.
        // We need a scenario where the change in MinSum actually changes Collect's result.
        // Better: Set MinSum to a value that after change makes Collect fail where before it would succeed.
        // Let's re-plan: Initialization with MinSum=50, then deposit 30 (so balance=30 < 50), then Collect(5) would normally fail because balance < MinSum.
        // But if later SetMinSum(5) is called (which shouldn't happen after init, but in bug version it does), then balance=30 >= 5, Collect(5) would succeed.
        // So: 
        // - Reference: after init, SetMinSum(5) reverts, MinSum stays 50, balance=30, Collect(5) fails.
        // - Bug: after init, SetMinSum(5) succeeds, MinSum becomes 5, balance=30, Collect(5) succeeds.
        // That yields a divergent revert boolean.

        // Reset: deploy new contract for simplicity
        c = new C();
        c.SetMinSum(50);
        c.SetLogFile(address(1));
        c.Initialized();

        // Now user Alice deposits 30
        address alice = address(0x123);
        vm.deal(alice, 30);
        vm.prank(alice);
        (bool depositOk,) = address(c).call{value: 30}(""); // triggers receive -> Deposit
        assertTrue(depositOk);

        // Now attempt SetMinSum(5) – in reference it reverts (caught), in bug it succeeds
        vm.prank(address(this));
        (bool setOk,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 5));
        // (We don't assert on setOk yet, but we will use its effect)

        // Now Alice tries to Collect(5)
        vm.prank(alice);
        (bool collectOk,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 5));

        // The assertion: In reference, Collect should fail (because MinSum=50 > balance=30), so collectOk == false.
        // In bug version, SetMinSum(5) succeeded, so MinSum=5 <= balance=30, Collect succeeds => collectOk == true.
        // So assertTrue(collectOk) will pass on reference? No, reference: collectOk false, so assertTrue(false) fails.
        // We need assertion that PASSES on reference and FAILS on bug.
        // So we assert that collectOk is false: assertTrue(!collectOk) will be true on reference, false on bug.
        assertTrue(!collectOk);
    }
}

