pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Sequence: 1. prank address(0x1), call SetMinSum(10) - in reference this should revert
        // 2. then prank address(0x1) and call Deposit with value 5
        // In reference: SetMinSum fails, so MinSum stays 0, condition balances[msg.sender] >= MinSum is true (0>=0)
        // and balances[msg.sender] >= _am is false (0>=5 false) so Collect does nothing
        // In modified: SetMinSum succeeds, MinSum=10, so condition balances[msg.sender] >= MinSum is false (0>=10 false)
        // so Collect does nothing
        // But we need divergence: use SetMinSum and then Deposit to see if MinSum was set or not
        // Actually: in reference, SetMinSum reverts, so MinSum remains 0
        // In modified, SetMinSum succeeds, MinSum=10
        // After Deposit with value 5, balance[0x1]=5
        // Now call Collect(5) - reference: balances[0x1]>=MinSum => 5>=0 true, balances[0x1]>=_am => 5>=5 true => collect succeeds
        // modified: balances[0x1]>=MinSum => 5>=10 false => collect does nothing
        // So we can check address(c).balance after Collect
        address alice = address(0x1);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        bool ok1;
        try c.SetMinSum(10) { ok1 = true; } catch { ok1 = false; }
        // reference: ok1 false, modified: ok1 true
        // But we need one assertion at end, so we must commit to a path:
        // Instead: we call SetMinSum, then Deposit, then Collect, then compare balances
        // Use try/catch for SetMinSum as needed
        vm.prank(alice);
        try c.SetMinSum(10) {} catch {}
        // After this, reference has MinSum=0, modified has MinSum=10
        vm.prank(alice);
        c.Deposit{value: 5}();
        // Now alice balance = 5
        vm.prank(alice);
        // Collect 5
        c.Collect(5);
        // reference: 5>=0 true, 5>=5 true -> sends 5 wei to alice, address(c).balance becomes 0
        // modified: 5>=10 false -> does nothing, address(c).balance remains 5
        assertEq(address(c).balance, 0);
    }
}

