contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 wei so Collect can work
        c.SetMinSum(1);
        // Set a dummy LogFile address (any non-zero address)
        c.SetLogFile(address(0xdead));
        // Initialize the contract (prevents further SetMinSum in reference)
        c.Initialized();
        // Now re-set the MinSum – in the reference, this will revert because intitalized is true
        // But we want to test the second version's differing behavior after a deposit
        // First, we need to cause a deposit in the second version which also sets intitalized
        // We'll deploy a new contract and use a fresh scenario
        // Actually, let's start fresh: deploy a new C (we can't in testRegression)
        // We'll just set up a scenario where the bug manifests differently
        // Simpler: The second version sets intitalized in Deposit. So after a deposit,
        // SetMinSum reverts (since intitalized is true). In reference, after deposit,
        // SetMinSum still works if not initialized. So we test that after deposit,
        // reference's SetMinSum succeeds (since we never called Initialized), while second reverts.
        // Let's deploy a new contract manually in the test
        // But we only have 'c' from setUp. We'll just use c and skip Initialized.
        // Actually, we need two different contract instances? No, we can just do the sequence
        // on the same c and the assertion will differentiate.
        // Let's simplify: We'll not call Initialized at all on reference.
        // After a deposit, reference allows SetMinSum; second version reverts.
        // So we'll call Deposit via receive() with 0 ether (minimal) to trigger the change.
        vm.deal(address(this), 1 ether);
        // Call deposit by sending 0 ether? Actually Deposit requires msg.value >=0, but the require check: balances[msg.sender] + msg.value >= balances[msg.sender] always holds.
        // But we need to actually send ether to make it meaningful? Not necessary, just call with 0.
        // However, receive() is external payable, so we can send 0.
        // But note: the second version adds 'intitalized = true' at end of Deposit.
        // So after any deposit, intitalized becomes true.
        // So:
        // Reference: initial intitalized false. We call Deposit (via send 0). intitalized stays false.
        // Then SetMinSum should succeed (require(!intitalized) passes).
        // Second version: after same Deposit, intitalized becomes true. Then SetMinSum reverts.
        vm.prank(address(0xb0b));
        (bool success,) = address(c).call{value: 0}(""); // triggers receive() -> Deposit()
        require(success, "deposit call failed");

        // Now attempt SetMinSum in both versions
        // We'll use a try-catch to catch revert
        bool ok;
        try c.SetMinSum(2) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == true; Second: ok == false
        assertTrue(ok);
    }
