        // But we need to use try/catch: bool ok; try c.Deposit{value: huge}() { ok = true; } catch { ok = false; } then assertTrue(!ok).
        // Let's compute: max uint256 ~ 1.15e77. current balance is 2e18. To overflow: msg.value > max - 2e18. So deposit 1e77.
        address alice2 = address(0x2);
        vm.deal(alice2, 1e78);
        vm.prank(alice2);
        // But reference: require((balance + msg.value) >= balance) checks for overflow, which it is, so revert.
        // Buggy: no check, so it succeeds, balance becomes huge.
        bool depositOk;
        try c.Deposit{value: 1e77}() { depositOk = true; } catch { depositOk = false; }
        // Reference: depositOk == false (revert). Buggy: depositOk == true (succeeds).
        // So assert that depositOk is false.
        assertTrue(!depositOk);
    }
}

