import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize, set MinSum to 0, log file needed
        vm.prank(address(this));
        c.SetMinSum(0);
        vm.prank(address(this));
        c.SetLogFile(address(new LogFile()));
        vm.prank(address(this));
        c.Initialized();

        // Alice deposits 1 wei
        address alice = address(0xABCD);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1}();

        // Check: after deposit, first log entry should have Data = "Put" (reference) not "Collect" (bug)
        string memory actualData = c.History(0);
        assertEq(actualData, "Put");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

